  "about_items": [
    {
      "n": "#60·32",
      "text": "This is a classic long-sleeve top made from soft viscose, cut with a simple crew neck and smooth, elongating lines that drape neatly over the dress underneath."
    },
    {
      "n": "#239·38",
      "text": "The midi dress is crafted from comfortable knit fabric with a flattering V-neckline and a cinched waist that defines your figure before flowing into an A-line skirt ending just below the knee."
    },
    {
      "n": "#417·24",
      "text": "This thick, ribbed wool scarf adds warmth and a touch of cozy texture in solid black; its weight keeps it from slipping while providing a sophisticated layer against the cool autumn air."
    },
    {
      "n": "#230·33",
      "text": "The jewelry set features intricate, dark beads clustered into a choker-style necklace and matching stud earrings, offering understated elegance with just enough visual interest to stand out against the monochrome outfit."
    },
    {
      "n": "#102·33",
      "text": "These shoes are made from polished black leather with a sleek pointed toe and a sturdy block heel that provides security and height, perfect for standing for long periods during the service."
    },
    {
      "n": "#149·33",
      "text": "A structured tote in smooth black leather features subtle white text detailing its heritage on the front panel; it offers ample space for your essentials while maintaining a clean, formal profile."
    }
  ]
